    align-items: baseline;
    gap: var(--space-2);
    margin-bottom: var(--space-3);
  }

  .pane-head :global(h1),
  .pane-head :global(h2) {
    margin: 0;
    font-family: var(--font-heading);
    font-weight: var(--font-heading-weight);
    font-size: 22px;
    letter-spacing: -0.01em;
  }

  .statute {
    margin: 0;
