          <dt>{row.term}</dt>
          <dd>
            {row.values.map((value) =>
              row.mail === true ? <a href={`mailto:${value}`}>{value}</a> : <span>{value}</span>,
            )}
          </dd>
        </>
      ))
    }
  </dl>

  {
    note !== undefined && (
      <aside class="note" role="note">
        <p class="note-title">{note.title}</p>
        <p class="note-body">{note.body}</p>
        {note.mail !== undefined && (
          <p class="note-body">
            <a href={`mailto:${note.mail}`}>{note.mail}</a>
          </p>
        )}
      </aside>
    )
  }
</section>

<style>
  .pane {
    display: flex;
    flex-direction: column;
    padding: calc(var(--space-6) + var(--space-1)) calc(var(--space-6) + var(--space-1));
  }

  /* In the three-up grid the panes are separated by a rule, as the board
     draws them. The last one carries none — a trailing rule against the
     frame's own border reads as a doubled line. */
  .pane.column {
    border-right: 1px solid var(--color-divider);
  }

  .pane.column:last-of-type {
    border-right: 0;
  }

  /* A lone pane has four short values and a closing note. Stacked, that is
     a ribbon down the left of a 1440px page; side by side, the two halves
     use the width the page actually has. */
  .pane.wide {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 26rem);
    column-gap: var(--space-8);
    align-items: start;
    padding-inline: 0;
  }

  .pane.wide .pane-head {
    grid-column: 1 / -1;
  }

  .pane-head {
    margin-bottom: var(--space-2);
  }

  .pane-head :global(h1),
  .pane-head :global(h2) {
    margin: 0;
    font-family: var(--font-heading);
    font-weight: var(--font-heading-weight);
    font-size: 26px;
    line-height: 1.15;
    letter-spacing: -0.02em;
  }

  /* The board sets these labels in accent-400. That step is decorative
     weight, not text weight: at 10.5px it does not clear WCAG 1.4.3 on
     either background. accent-700 is the step contrast.test.ts asserts at
     4.5:1, and is what .card-kicker in modernist.css already uses for the
     same treatment. */
  .kicker {
    margin: var(--space-1) 0 0;
    font-size: 10.5px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-accent-700);
    font-weight: 800;
  }

  .rows {
    display: grid;
    margin: 0;
  }

  .rows dt {
    margin-top: var(--space-4);
    font-size: 10.5px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 800;
    color: var(--ink-muted);
  }

  .rows dd {
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    margin: var(--space-2) 0 0;
    font-size: 14px;
    line-height: 1.55;
    text-wrap: pretty;
  }

  /* One pane alone: the term sits beside its value so the pair spans the
     page instead of running down its left edge. */
  /* NOT `baseline`. The term and its value each carry a border-top, and
     they are set at different sizes — 10.5px uppercase against 14px. On a
     baseline, the two boxes are offset by the difference between those
     baselines, and each takes its border with it, so the two halves of
     what should be one rule land on different lines. `start` puts both box
     tops on the grid row, which is where the rule belongs. */
  .pane.wide .rows {
    grid-template-columns: minmax(9rem, 14rem) 1fr;
    align-items: start;
  }

  .pane.wide .rows dt {
    padding-right: var(--space-6);
    border-top: 1px solid var(--color-divider);
    padding-top: var(--space-4);
    margin-top: 0;
  }

  .pane.wide .rows dd {
    border-top: 1px solid var(--color-divider);
    padding-top: var(--space-4);
    margin-top: 0;
  }

  .rows a {
    color: var(--color-accent-700);
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  /* `margin-top: auto` is the board's own: the closing note sits on the
     floor of its column, so three panes of different lengths still end on
     one line. */
  .note {
    margin-top: auto;
    padding-top: var(--space-6);
  }

  .pane.wide .note {
    margin-top: 0;
  }

  .pane.wide .note .note-title {
    margin-top: var(--space-4);
  }

  .note-title {
    margin: var(--space-6) 0 var(--space-2);
    padding-top: var(--space-3);
    border-top: 1px solid var(--border-strong);
    font-size: 13px;
    font-weight: 700;
  }

  .note-body {
    margin: 0;
    font-size: 13px;
    line-height: 1.55;
    color: var(--ink-muted);
    text-wrap: pretty;
  }

  .note-body + .note-body {
    margin-top: var(--space-2);
  }

  .note-body a {
    color: var(--color-accent-700);
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  @media (max-width: 900px) {
    .pane.wide {
      grid-template-columns: 1fr;
    }

    .pane.wide .note {
      margin-top: var(--space-4);
    }

    .pane.column {
      border-right: 0;
      border-bottom: 1px solid var(--color-divider);
    }

    .pane.column:last-of-type {
      border-bottom: 0;
    }

    .note {
      margin-top: 0;
    }
  }

  /* A two-column term/value pair at 390px is a horizontal scroll the
     reader has to discover. The cohort this ships for is 40+ and arrives
     on a phone. */
  @media (max-width: 660px) {
    .pane {
      padding-inline: 0;
    }

    .pane.wide .rows {
      grid-template-columns: 1fr;
    }

    .pane.wide .rows dd {
      border-top: 0;
      padding-top: 0;
      margin-top: var(--space-2);
    }
  }
</style>

