import { describe, expect, it } from 'vitest';

import { cashbackStrings } from '../../i18n/cashback';
import { READING_LANGUAGES } from '../reader/axes';
import { uiStrings } from '../reader/strings';
import { faqStrings } from './strings';

/** Every sentence some catalogue already renders on a screen, for a language. */
function shippedSentences(lang: (typeof READING_LANGUAGES)[number]): Set<string> {
  return new Set(
    [...Object.values(cashbackStrings(lang)), ...Object.values(uiStrings(lang))].filter(
      (value): value is string => typeof value === 'string',
    ),
  );
}

describe('faqStrings', () => {
  it('answers in the language asked', () => {
    expect(faqStrings('el').heading).toBe('Συχνές ερωτήσεις');
    expect(faqStrings('de').heading).toBe('Häufige Fragen');
  });

  it('answers only in sentences that already ship on a screen', () => {
    // The board's own rule, and the reason this module owns no answer:
    // "A FAQ that paraphrases the product is a second source of truth."
    //
    // Set membership, never `toContain`. It fails the moment somebody
    // hand-writes an answer here, edits a catalogue sentence only here, or
    // "tidies" one with a trailing space — which is the drift the FAQ warns
    // about on its own face, caught in CI rather than in review.
    for (const lang of READING_LANGUAGES) {
      const shipped = shippedSentences(lang);
      for (const section of faqStrings(lang).sections) {
        for (const entry of section.entries) {
          for (const paragraph of entry.answer) {
            expect(shipped.has(paragraph), `${lang}: "${paragraph}"`).toBe(true);
          }
        }
      }
    }
  });

  it('renders the two answers no other surface has ever rendered', () => {
    // approvalStep1 and approvalStep3 were carried in both catalogues,
    // referenced by nothing. This page is what they were written for; if a
    // future edit drops them, that is a decision to take deliberately.
    for (const lang of READING_LANGUAGES) {
      const c = cashbackStrings(lang);
      const answers = faqStrings(lang).sections.flatMap((section) =>
        section.entries.flatMap((entry) => entry.answer),
      );
      expect(answers).toContain(c.approvalStep1);
      expect(answers).toContain(c.approvalStep3);
    }
  });

  it('has the same shape in every alpha language', () => {
    // A missing translation is a red test, not a blank line on a page.
    const shapes = READING_LANGUAGES.map((lang) =>
      faqStrings(lang).sections.map((section) =>
        section.entries.map((entry) => entry.answer.length),
      ),
    );
    for (const shape of shapes) {
      expect(shape).toEqual(shapes[0]);
    }
  });

  it('carries every string in every alpha language (FR-015)', () => {
    for (const lang of READING_LANGUAGES) {
      const t = faqStrings(lang);
      for (const key of ['heading', 'intro', 'noAnswerHere', 'contact'] as const) {
        expect(t[key], `${lang}.${key}`).not.toBe('');
      }
      expect(t.sections.length).toBeGreaterThan(0);
      for (const section of t.sections) {
        expect(section.heading, `${lang} section heading`).not.toBe('');
        expect(section.entries.length).toBeGreaterThan(0);
        for (const entry of section.entries) {
          expect(entry.question, `${lang} question`).not.toBe('');
          expect(entry.answer.length).toBeGreaterThan(0);
        }
      }
    }
  });

  it('asks each question once and answers each with its own sentence', () => {
    // Two entries pointing at one constant is a copy-paste the types cannot
    // see, and reads to a member as the same answer given twice.
    for (const lang of READING_LANGUAGES) {
      const entries = faqStrings(lang).sections.flatMap((section) => section.entries);
      const questions = entries.map((entry) => entry.question);
      const answers = entries.map((entry) => entry.answer.join('�'));

      expect(new Set(questions).size, `${lang} repeats a question`).toBe(questions.length);
      expect(new Set(answers).size, `${lang} repeats an answer`).toBe(answers.length);
    }
  });

  it('holds no money and no product name', () => {
    // The board asks "I requested 10,00 €"; a threshold frozen into a
    // translated string is the drift this page exists to prevent (FR-071),
    // and a new file has a brand-literal budget of zero.
    const forbidden = /\d[.,]\d{2}|€|epiloyes/i;
    for (const lang of READING_LANGUAGES) {
      const t = faqStrings(lang);
      for (const own of [t.intro, t.noAnswerHere, t.heading]) {
        expect(own, `${lang}: "${own}"`).not.toMatch(forbidden);
      }
      for (const section of t.sections) {
        for (const entry of section.entries) {
          expect(entry.question, `${lang}: "${entry.question}"`).not.toMatch(forbidden);
        }
      }
    }
  });

  it('titles itself with the label the footer links', () => {
    for (const lang of READING_LANGUAGES) {
      expect(faqStrings(lang).heading).toBe(uiStrings(lang).faqLabel);
    }
  });
});

