cd "C:/Users/madym/repos/apivo-news" && PYTHONIOENCODING=utf-8 python - <<'PY'
p='web/src/pages/[lang]/faq.astro'
s=open(p,encoding='utf-8').read()
old = """  .q {
    padding: var(--space-4) 0;
    border-bottom: 1px solid var(--color-divider);
  }"""
new = """  /* No rule between entries while there are two columns. The columns are
     independent grids whose entries wrap to different heights, so a rule per
     entry lands at a different y in each and the pair reads as ragged rather
     than ruled. The section rule above still spans both and does align, and
     that is the one this layout needs. The per-entry rule returns below,
     where a single column makes it a list separator again. */
  .q {
    padding: var(--space-4) 0 var(--space-6);
  }"""
assert old in s
s = s.replace(old, new)

old2 = """  @media (max-width: 900px) {
    .groups {
      grid-template-columns: 1fr;
    }
  }"""
new2 = """  @media (max-width: 900px) {
    .groups {
      grid-template-columns: 1fr;
    }

    .q {
      padding-bottom: var(--space-4);
      border-bottom: 1px solid var(--color-divider);
    }
  }"""
assert old2 in s
open(p,'w',encoding='utf-8').write(s.replace(old2, new2))
print('per-entry rules confined to the single-column layout')
