3	import { cashbackStrings } from '../../i18n/cashback';
4	import { READING_LANGUAGES } from '../reader/axes';
5	import { uiStrings } from '../reader/strings';
6	import { faqStrings } from './strings';
7	
8	/** Every sentence some catalogue already renders on a screen, for a language. */
9	function shippedSentences(lang: (typeof READING_LANGUAGES)[number]): Set<string> {
10	  return new Set(
11	    [...Object.values(cashbackStrings(lang)), ...Object.values(uiStrings(lang))].filter(
12	      (value): value is string => typeof value === 'string',
13	    ),
14	  );
15	}
16	
17	describe('faqStrings', () => {
18	  it('answers in the language asked', () => {
19	    expect(faqStrings('el').heading).toBe('Συχνές ερωτήσεις');
20	    expect(faqStrings('de').heading).toBe('Häufige Fragen');
21	  });
22	
23	  it('answers only in sentences that already ship on a screen', () => {
24	    // The board's own rule, and the reason this module owns no answer:
25	    // "A FAQ that paraphrases the product is a second source of truth."
26	    //
27	    // Set membership, never `toContain`. It fails the moment somebody
28	    // hand-writes an answer here, edits a catalogue sentence only here, or
29	    // "tidies" one with a trailing space — which is the drift the FAQ warns
30	    // about on its own face, caught in CI rather than in review.
31	    for (const lang of READING_LANGUAGES) {
32	      const shipped = shippedSentences(lang);
33	      for (const section of faqStrings(lang).sections) {
34	        for (const entry of section.entries) {
35	          for (const paragraph of entry.answer) {
36	            expect(shipped.has(paragraph), `${lang}: "${paragraph}"`).toBe(true);
37	          }
38	        }
39	      }
40	    }
41	  });
42	
43	  it('renders the two answers no other surface has ever rendered', () => {
44	    // approvalStep1 and approvalStep3 were carried in both catalogues,
45	    // referenced by nothing. This page is what they were written for; if a
46	    // future edit drops them, that is a decision to take deliberately.
47	    for (const lang of READING_LANGUAGES) {
48	      const c = cashbackStrings(lang);
49	      const answers = faqStrings(lang).sections.flatMap((section) =>
50	        section.entries.flatMap((entry) => entry.answer),
51	      );
52	      expect(answers).toContain(c.approvalStep1);
53	      expect(answers).toContain(c.approvalStep3);
54	    }
55	  });
56	
57	  it('has the same shape in every alpha language', () => {
58	    // A missing translation is a red test, not a blank line on a page.
59	    const shapes = READING_LANGUAGES.map((lang) =>
60	      faqStrings(lang).sections.map((section) =>
61	        section.entries.map((entry) => entry.answer.length),
62	      ),
63	    );
64	    for (const shape of shapes) {
65	      expect(shape).toEqual(shapes[0]);
66	    }
67	  });
68	
