70	    for (const lang of READING_LANGUAGES) {
71	      const t = faqStrings(lang);
72	      for (const key of ['heading', 'intro', 'noAnswerHere', 'contact'] as const) {
73	        expect(t[key], `${lang}.${key}`).not.toBe('');
74	      }
75	      expect(t.sections.length).toBeGreaterThan(0);
76	      for (const section of t.sections) {
